def validate(binary):
    import hashlib
    for address,want in CHECKS.items():
        ins=list(binary.cs.disasm(binary.read(address,4),address))
        if len(ins)!=1 or hashlib.sha256((ins[0].mnemonic+' '+ins[0].op_str).encode()).hexdigest()!=want:
            raise ValueError('Local firmware instruction digest mismatch')
    if hashlib.sha256(binary.read(0x1EF096,64)).hexdigest()!='70ea51f77455579784193f8cc276a388f1cebc1e555900fa26d7f758ed5599e2':raise ValueError('Local firmware message digest mismatch')
    return CHECKS
